import re

PADROES = {
    "CPF": r"\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b",
    "EMAIL": r"\b[\w.+-]+@[\w-]+\.[\w.]+\b",
    "TELEFONE": r"\(?\b\d{2}\)?\s?9?\d{4}-?\d{4}\b",
}

def mascarar(texto: str) -> str:
    for rotulo, padrao in PADROES.items():
        texto = re.sub(padrao, f"[{rotulo}]", texto)
    return texto

